<style>:root{--bg:#f6f8fb;--surface:#fff;--text:#122033;--muted:#637083;--border:#d8e2ee;--accent:#155ea8;--soft:#eef4fb;--danger:#b42318;--success-bg:#e7f5ee;--success-border:#b8dec9;font-family:"Instrument Sans",ui-sans-serif,system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text)}.page{min-height:100vh;padding:40px 24px}.wrap{width:min(100%,1050px);margin:auto}.header{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;border-bottom:1px solid var(--border);padding-bottom:24px}.brand{margin:0 0 4px;color:var(--accent);font-size:14px;font-weight:700}h1{margin:0;font-size:clamp(28px,4vw,36px)}h2{margin:0 0 5px;font-size:20px}p{margin-top:0}.tabs{display:flex;gap:4px;border:1px solid var(--border);border-radius:8px;background:#fff;padding:4px}.tab{border-radius:6px;color:var(--muted);padding:8px 14px;font-size:14px;font-weight:700;text-decoration:none}.tab.active{background:var(--accent);color:#fff}.module-tabs{display:flex;gap:24px;margin-top:24px;border-bottom:1px solid var(--border)}.module-tab{border-bottom:3px solid transparent;color:var(--muted);padding:0 2px 12px;font-size:14px;font-weight:750;text-decoration:none}.module-tab.active{border-color:var(--accent);color:var(--accent)}.panel{margin-top:24px;border:1px solid var(--border);border-radius:8px;background:#fff;padding:24px;box-shadow:0 8px 24px rgba(18,32,51,.06)}.status{margin-top:24px;border:1px solid var(--success-border);border-radius:8px;background:var(--success-bg);padding:12px 16px}.search,.company-select{display:grid;grid-template-columns:1fr auto auto;gap:10px;align-items:end}.company-select{grid-template-columns:1fr auto;margin-top:18px}.field label{display:block;margin-bottom:8px;font-size:14px;font-weight:700}input,select{width:100%;border:1px solid #c8d5e4;border-radius:6px;background:#fff;padding:10px 12px;font:inherit}.button{display:inline-block;border:0;border-radius:6px;background:var(--accent);color:#fff;padding:11px 15px;font:inherit;font-size:14px;font-weight:700;text-decoration:none;cursor:pointer}.clear{color:var(--accent);padding:11px;text-decoration:none;font-weight:700}.hint{color:var(--muted);font-size:14px}.term-box{margin-top:24px;border:1px solid var(--border);border-radius:8px;background:var(--soft);padding:20px}.student-picker{max-height:250px;overflow:auto;margin:14px 0;border:1px solid var(--border);border-radius:6px;background:#fff}.student-option{display:flex;gap:10px;padding:11px 12px;border-bottom:1px solid var(--border);font-size:14px}.student-option input{width:auto}.term-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.error{color:var(--danger);font-size:13px}.term-row{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:14px 0;border-top:1px solid var(--border)}.actions{display:flex;gap:8px}.link,.delete{border:0;background:transparent;color:var(--accent);padding:8px;font:inherit;font-weight:700;text-decoration:none;cursor:pointer}.delete{color:var(--danger)}.empty{text-align:center;color:var(--muted);padding:30px}@media(max-width:650px){.page{padding:24px 14px}.header{align-items:flex-start;flex-direction:column}.tabs{width:100%;overflow:auto}.search,.company-select,.term-grid{grid-template-columns:1fr}.module-tabs{gap:14px;overflow:auto}.module-tab{white-space:nowrap}}</style></head><body><div class="page"><main class="wrap">
