</main></div><script>document.addEventListener('DOMContentLoaded',()=>{const search=document.getElementById('student-search');const list=document.getElementById('students');const options=[...document.querySelectorAll('#students .student-option')];if(!search||!list||!options.length)return;const normalize=value=>value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();const digits=value=>value.replace(/\D/g,'');const tools=document.createElement('div');tools.className='student-search-tools';tools.innerHTML='<p class="student-search-status" aria-live="polite"></p><div class="student-search-actions"><button class="student-tool select-visible" type="button">Selecionar visíveis</button><button class="student-tool clear-selected" type="button">Limpar seleção</button></div>';search.closest('.field').after(tools);const status=tools.querySelector('.student-search-status');const noResults=document.createElement('div');noResults.className='student-no-results';noResults.textContent='Nenhum aluno encontrado.';noResults.hidden=true;list.appendChild(noResults);const updateStatus=()=>{const visible=options.filter(option=>!option.hidden).length;const selected=options.filter(option=>option.querySelector('input').checked).length;status.textContent=`${visible} resultado${visible===1?'':'s'} · ${selected} selecionado${selected===1?'':'s'}`;options.forEach(option=>option.classList.toggle('is-selected',option.querySelector('input').checked));noResults.hidden=visible!==0};const filter=()=>{const term=normalize(search.value);const cpf=digits(search.value);const ranked=options.map((option,index)=>{const value=normalize(option.dataset.search||'');const optionCpf=digits(option.dataset.search||'');let score=term===''?0:value.startsWith(term)?1:value.includes(term)?2:(cpf&&optionCpf.startsWith(cpf))?1:(cpf&&optionCpf.includes(cpf))?2:99;return{option,index,score}}).sort((a,b)=>a.score-b.score||a.index-b.index);ranked.forEach(item=>{item.option.hidden=item.score===99;list.insertBefore(item.option,noResults)});updateStatus()};search.addEventListener('input',filter);options.forEach(option=>option.querySelector('input').addEventListener('change',updateStatus));tools.querySelector('.select-visible').addEventListener('click',()=>{options.filter(option=>!option.hidden).forEach(option=>option.querySelector('input').checked=true);updateStatus()});tools.querySelector('.clear-selected').addEventListener('click',()=>{options.forEach(option=>option.querySelector('input').checked=false);updateStatus()});filter()});</script></body></html>
